def _matcher_revision(words: frozenset[str]) -> str:
    payload = json.dumps(
        ["wuwaterm-cjk-matcher-v1", JIEBA_COMMIT, LEXICON_FILTER, sorted(words)],
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode()
    return hashlib.sha256(payload).hexdigest()


MATCHER_REVISION = _matcher_revision(_WORDS)
